from dataclasses import dataclass
from textwrap import dedent


@dataclass(frozen=True)
class CharacterPromptCase:
    id: str
    name: str
    prompt: str
    relationship: str
    chat_rule: str


@dataclass(frozen=True)
class ChatCase:
    id: str
    content: str


@dataclass(frozen=True)
class CharacterChatCase:
    id: str
    name: str
    prompt: str
    relationship: str
    content: str
    chat_rule: str


